import * as url from 'node:url';
function main(): void {
  const u: any = url.parse('http://user:pw@Host.com:8080/p/a/t/h?query=string#hash', true);
  console.log(u.protocol, u.auth, u.host, u.port, u.hostname, u.hash, u.search, JSON.stringify(u.query), u.pathname, u.path, u.href);
  console.log(url.resolve('/one/two/three', 'four'), url.resolve('http://example.com/', '/one'), url.resolve('http://example.com/one', '/two'));
  console.log(url.format({ protocol: 'https', hostname: 'example.com', pathname: '/some/path', query: { page: 1, format: 'json' } }));
  const x = new url.Url();
  console.log(x.protocol, Object.keys(x).length);
  console.log(JSON.stringify((url as any).resolveObject('http://a.com/b/c', '../d')));
  function t(f: () => any): string { try { return String(f()); } catch (e: any) { return 'THROW ' + e.name + ' ' + e.code + ': ' + e.message; } }
  const d: any = url.domainToASCII, e: any = url.parse, fm: any = url.format;
  console.log(t(() => d()), '|', t(() => e()), '|', t(() => fm(5)), '|', t(() => url.domainToASCII('español.com')), '|', t(() => url.domainToUnicode('xn--espaol-zwa.com')));
  console.log(url.fileURLToPath.length, (url as any).fileURLToPathBuffer.length, (url as any).resolveObject.length, url.resolve.length);
  console.log(url.format(new URL('https://a:b@測試?abc#foo'), { fragment: false, unicode: true, auth: false }));
  console.log(JSON.stringify(url.parse('//foo/bar', false, true)));
}
